{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["header","invoice-records"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"title":"Review extracted invoices"},"children":[]}}
{"op":"add","path":"/elements/invoice-records","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"repeat":{"statePath":"/result","key":"invoice_id"},"children":["record-header","amount-band","purchase-details","parties","verification","record-separator"]}}
{"op":"add","path":"/elements/record-header","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["vendor-heading","document-type"]}}
{"op":"add","path":"/elements/vendor-heading","value":{"type":"Heading","props":{"text":{"$item":"vendor"},"level":"h2"},"visible":{"$item":"vendor"},"children":[]}}
{"op":"add","path":"/elements/document-type","value":{"type":"Badge","props":{"text":{"$item":"category/category"},"variant":"default"},"visible":{"$item":"category/category"},"children":[]}}
{"op":"add","path":"/elements/amount-band","value":{"type":"Grid","props":{"columns":3,"gap":"lg"},"children":["total-including-tax","before-tax","tax"]}}
{"op":"add","path":"/elements/total-including-tax","value":{"type":"Detail","props":{"label":"Total including tax","value":{"$item":"amount_incl_tax"}},"children":[]}}
{"op":"add","path":"/elements/before-tax","value":{"type":"Detail","props":{"label":"Before tax","value":{"$item":"amount_excl_tax"}},"children":[]}}
{"op":"add","path":"/elements/tax","value":{"type":"Detail","props":{"label":"Tax","value":{"$item":"vat_amount"}},"children":[]}}
{"op":"add","path":"/elements/purchase-details","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["document-number","issued-line","transaction-time","purchase-description"]}}
{"op":"add","path":"/elements/document-number","value":{"type":"Detail","props":{"label":"Document number","value":{"$item":"invoice_number"}},"children":[]}}
{"op":"add","path":"/elements/issued-line","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"visible":{"$item":"issue_date"},"children":["issued-label","issued-date"]}}
{"op":"add","path":"/elements/issued-label","value":{"type":"Text","props":{"text":"Issued","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/issued-date","value":{"type":"DateText","props":{"value":{"$item":"issue_date"},"style":"long","tone":"muted"},"children":[]}}
{"op":"add","path":"/elements/transaction-time","value":{"type":"Detail","props":{"label":"Time","value":{"$item":"time"}},"children":[]}}
{"op":"add","path":"/elements/purchase-description","value":{"type":"Detail","props":{"label":"Purchase","value":{"$item":"description"}},"children":[]}}
{"op":"add","path":"/elements/parties","value":{"type":"Split","props":{"ratio":"1:1","gap":"lg"},"children":["seller-details","buyer-details"]}}
{"op":"add","path":"/elements/seller-details","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"visible":{"$or":[{"$item":"vendor_address"},{"$item":"vendor_siret"},{"$item":"vendor_vat_number"}]},"children":["seller-address","seller-siret","seller-vat-number"]}}
{"op":"add","path":"/elements/seller-address","value":{"type":"Detail","props":{"label":"Seller address","value":{"$item":"vendor_address"}},"children":[]}}
{"op":"add","path":"/elements/seller-siret","value":{"type":"Detail","props":{"label":"SIRET","value":{"$item":"vendor_siret"}},"children":[]}}
{"op":"add","path":"/elements/seller-vat-number","value":{"type":"Detail","props":{"label":"VAT number","value":{"$item":"vendor_vat_number"}},"children":[]}}
{"op":"add","path":"/elements/buyer-details","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"visible":{"$or":[{"$item":"company_name"},{"$item":"company_address"}]},"children":["buyer-name","buyer-address"]}}
{"op":"add","path":"/elements/buyer-name","value":{"type":"Detail","props":{"label":"Buyer","value":{"$item":"company_name"}},"children":[]}}
{"op":"add","path":"/elements/buyer-address","value":{"type":"Detail","props":{"label":"Buyer address","value":{"$item":"company_address"}},"children":[]}}
{"op":"add","path":"/elements/verification","value":{"type":"Collapsible","props":{"title":"Check the extraction","defaultOpen":false},"visible":{"$or":[{"$item":"category/explanation"},{"$item":"vat_rates"},{"$item":"text"}]},"children":["verification-content"]}}
{"op":"add","path":"/elements/verification-content","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["classification-reasoning","tax-rates","source-label","source-text"]}}
{"op":"add","path":"/elements/classification-reasoning","value":{"type":"Detail","props":{"label":"Why this document type","value":{"$item":"category/explanation"}},"children":[]}}
{"op":"add","path":"/elements/tax-rates","value":{"type":"MthdsResult","props":{"path":"vat_rates"},"visible":{"$item":"vat_rates"},"children":[]}}
{"op":"add","path":"/elements/source-label","value":{"type":"Text","props":{"text":"Source text","variant":"muted"},"visible":{"$item":"text"},"children":[]}}
{"op":"add","path":"/elements/source-text","value":{"type":"Text","props":{"text":{"$item":"text"},"variant":"code"},"visible":{"$item":"text"},"children":[]}}
{"op":"add","path":"/elements/record-separator","value":{"type":"Separator","props":{"orientation":"horizontal"},"children":[]}}
